import{_ as i,o as a,c as e,a2 as r}from"./chunks/framework.DSc8fo6x.js";const c=JSON.parse('{"title":"Что нового","description":"","frontmatter":{},"headers":[],"relativePath":"ru/yenilikler.md","filePath":"ru/yenilikler.md"}'),t={name:"ru/yenilikler.md"};function o(n,l,s,h,_,d){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="что-нового" tabindex="-1">Что нового <a class="header-anchor" href="#что-нового" aria-label="Permalink to &quot;Что нового&quot;">​</a></h1><p>Изменения по версиям программы (новые — сверху).</p><h2 id="_12-10-2026" tabindex="-1">12.10.2026 <a class="header-anchor" href="#_12-10-2026" aria-label="Permalink to &quot;12.10.2026&quot;">​</a></h2><ul><li>Помощь: меню «Помощь» слева внизу и «?» на каждой странице — инструкция открывается в программе, без интернета (3 языка).</li><li>Памятка кассира для печати (PDF), горячие клавиши.</li><li>Список «Начало работы» для админа: данные магазина, первый товар, кассир, принтер, Telegram.</li><li>Онлайн-инструкция, видео и PDF: camalzadeh.github.io/kassa-docs</li><li>Режим обучения: новый кассир учится продавать, продажи не записываются (включает только админ, на время).</li><li>Исправлено: в Настройках несохранённые изменения на медленном компьютере могли сами стираться.</li></ul><h2 id="_12-10-2026-1" tabindex="-1">12.10.2026 <a class="header-anchor" href="#_12-10-2026-1" aria-label="Permalink to &quot;12.10.2026&quot;">​</a></h2><ul><li>Telegram: после «Найти чат» и успешного пробного сообщения токен и чат сохраняются автоматически.</li><li>Все настройки (и значения по умолчанию) хранятся в базе — при переносе базы всё восстанавливается.</li><li>Вместо старой чёрной иконки везде отображается новый логотип Kassa.</li></ul><h2 id="_11-10-2026" tabindex="-1">11.10.2026 <a class="header-anchor" href="#_11-10-2026" aria-label="Permalink to &quot;11.10.2026&quot;">​</a></h2><ul><li>Принтер чеков и этикеток (например, Xprinter): Настройки → Принтеры. Чек и этикетки печатаются сразу, без окна печати; пробная печать.</li><li>Чек может печататься автоматически после продажи; иначе — кнопка «Чек» в зелёном уведомлении.</li><li>При оплате наличными может открываться денежный ящик (если он подключён к принтеру).</li><li>Новые размеры этикеток: 50×30, 40×30, 30×20 мм.</li><li>Telegram: исправлена отправка в группу — если найдено несколько чатов, выберите нужный из списка.</li><li>Если Telegram не работает больше 2 дней или в базе найдено повреждение, админ видит предупреждение на главном экране.</li><li>Сканирование больше не обрывается (штрихкод не делится на части); экран не зависает после восстановления.</li><li>Для новой установки нужен пароль установки.</li></ul><h2 id="_07-10-2026" tabindex="-1">07.10.2026 <a class="header-anchor" href="#_07-10-2026" aria-label="Permalink to &quot;07.10.2026&quot;">​</a></h2><ul><li>Языки: азербайджанский, русский, английский. Каждый пользователь может выбрать свой язык в меню.</li><li>Новый раздел «Настройки»: данные магазина (видны в чеке), тема, размер текста, время блокировки, бэкап и др. Все настройки хранятся в базе.</li><li>Перед обновлением база автоматически сохраняется; старая версия программы не открывает новую базу.</li><li>Если база удалена или повреждена, программа не создаёт новую — открывается экран восстановления (по коду восстановления).</li><li>Бэкап можно восстановить прямо из программы, а базу — перенести на другой диск.</li><li>Если базу подменили старой копией, пока программа была закрыта, админ получит предупреждение.</li><li>Обновления подписаны: программа устанавливает только официальные версии (из интернета или из файла).</li><li>Telegram: ежедневный отчёт и зашифрованный бэкап на телефон владельца.</li></ul>',10)])])}const m=i(t,[["render",o]]);export{c as __pageData,m as default};
